[standards/technology/nextjs/STD-TEC-NXT-005-security-scanning.md#43-custom-rules]

### 4.3 Custom Rules

Implement custom security rules:

```typescript
// security/rules/csrf-protection.js
module.exports = {
    meta: {
        type: 'problem',
        docs: {
            description: 'Enforce CSRF protection on forms',
            category: 'Security',
            recommended: true,
        },
    },
    create(context) {
        return {
            JSXElement(node) {
                if (node.openingElement.name.name === 'form') {
                    const hasCSRFToken = node.openingElement.attributes.some(
                        (attr) => attr.name && attr.name.name === 'csrf'
                    );

                    if (!hasCSRFToken) {
                        context.report({
                            node,
                            message: 'Forms must include CSRF protection',
                        });
                    }
                }
            },
        };
    },
};
```

