[standards/technology/nextjs/STD-TEC-NXT-005-security-scanning.md#52-response-times]

### 5.2 Response Times

Implement response time monitoring:

```typescript
// security/monitoring/response-times.ts
interface VulnerabilityAlert {
    severity: 'critical' | 'high' | 'medium' | 'low';
    detectedAt: Date;
    resolvedAt?: Date;
    description: string;
}

function checkResponseTime(alert: VulnerabilityAlert): boolean {
    const responseTime = alert.resolvedAt
        ? alert.resolvedAt.getTime() - alert.detectedAt.getTime()
        : Date.now() - alert.detectedAt.getTime();

    const maxResponseTimes = {
        critical: 24 * 60 * 60 * 1000, // 24 hours
        high: 72 * 60 * 60 * 1000, // 72 hours
        medium: 14 * 24 * 60 * 60 * 1000, // 2 weeks
        low: 30 * 24 * 60 * 60 * 1000, // 1 month
    };

    return responseTime <= maxResponseTimes[alert.severity];
}
```

